const BRANDS = [...new Set(TIRE_ROWS.map(r => r.brand))].sort();
const CATEGORIES = [...new Set(TIRE_ROWS.map(r => r.category))].sort();
const DIAMETERS = [...new Set(TIRE_ROWS.map(r => r.diameter))].sort((a,b) => a-b);
const WIDTHS = [...new Set(TIRE_ROWS.map(r => r.width))].sort((a,b) => a-b);
const ASPECTS = [...new Set(TIRE_ROWS.map(r => r.aspect).filter(a => a !== null))].sort((a,b) => a-b);
const SIZES = [...new Set(TIRE_ROWS.map(r => r.size))].sort((a,b) => {
  const pa = a.match(/^(\d+(?:\.\d+)?)/), pb = b.match(/^(\d+(?:\.\d+)?)/);
  return parseFloat(pa[1]) - parseFloat(pb[1]);
});